    _fsFavKeyDe: function (l) { var FS = window.FolhaSemanal; var fav = (l.favorecido || l.nome || "—"); return String(fav).toUpperCase().replace(/\s+/g, " ").trim() + "|" + String(l.chavePix || "").trim(); },
