        var wb = new ExcelJS.Workbook(); wb.creator = (typeof Empresa !== "undefined" && Empresa.excelCreator) ? Empresa.excelCreator() : (emp.nome || "OrçaPRO IA");
        var NAVY = "FF0F2740", VERDE = "FF16A34A", MOEDA = '"R$" #,##0.00';
