          if (typeof Auth !== "undefined" && Auth.podeModulo && !Auth.podeModulo("fiscal")) { UI.toast("Seu usuário não tem permissão no módulo Fiscal.", "erro"); return; }
          return this.lancarDocumento("fiscal");
